import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";

/**
 * Test all available category sorting options comprehensively.
 *
 * This test validates the sorting functionality of the discussion board
 * categories API by testing all available sort fields (display_order,
 * created_at, name) and both sort directions (ascending and descending). It
 * verifies that:
 *
 * 1. Default sorting by display_order in ascending order works correctly
 * 2. Sorting by created_at in ascending order (oldest first) returns correct
 *    sequence
 * 3. Sorting by created_at in descending order (newest first) returns correct
 *    sequence
 * 4. Sorting by name alphabetically in ascending order works correctly
 * 5. Sorting by name alphabetically in descending order works correctly
 * 6. Pagination works correctly with sorting applied
 * 7. No sort parameters defaults to display_order ascending behavior
 *
 * These tests ensure that the API properly handles sort parameters and returns
 * categories in the expected order for different use cases.
 */
export async function test_api_category_sort_options(
  connection: api.IConnection,
) {
  const limit = 10;

  // Test 1: Default sorting (no sort parameters) - should sort by display_order ascending
  const defaultSortResult: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        limit,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(defaultSortResult);

  // Verify default sort returns results
  TestValidator.predicate(
    "default sort should return categories",
    defaultSortResult.data.length > 0,
  );

  // Verify default sort is by display_order ascending (if multiple items)
  if (defaultSortResult.data.length > 1) {
    for (let i = 0; i < defaultSortResult.data.length - 1; i++) {
      TestValidator.predicate(
        `default sort display_order should be ascending at position ${i}`,
        defaultSortResult.data[i].display_order <=
          defaultSortResult.data[i + 1].display_order,
      );
    }
  }

  // Test 2: Explicit sorting by display_order ascending
  const displayOrderAscResult: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        order_by: "display_order",
        direction: "asc",
        limit,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(displayOrderAscResult);

  // Verify display_order ascending sort
  if (displayOrderAscResult.data.length > 1) {
    for (let i = 0; i < displayOrderAscResult.data.length - 1; i++) {
      TestValidator.predicate(
        `display_order ascending sort at position ${i}`,
        displayOrderAscResult.data[i].display_order <=
          displayOrderAscResult.data[i + 1].display_order,
      );
    }
  }

  // Test 3: Sorting by created_at ascending (oldest first)
  const createdAtAscResult: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        order_by: "created_at",
        direction: "asc",
        limit,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(createdAtAscResult);

  TestValidator.predicate(
    "created_at ascending sort should return categories",
    createdAtAscResult.data.length >= 0,
  );

  // Test 4: Sorting by created_at descending (newest first)
  const createdAtDescResult: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        order_by: "created_at",
        direction: "desc",
        limit,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(createdAtDescResult);

  TestValidator.predicate(
    "created_at descending sort should return categories",
    createdAtDescResult.data.length >= 0,
  );

  // Test 5: Sorting by name ascending (alphabetically)
  const nameAscResult: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        order_by: "name",
        direction: "asc",
        limit,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(nameAscResult);

  // Verify name ascending sort
  if (nameAscResult.data.length > 1) {
    for (let i = 0; i < nameAscResult.data.length - 1; i++) {
      TestValidator.predicate(
        `name ascending sort at position ${i}`,
        nameAscResult.data[i].name.localeCompare(
          nameAscResult.data[i + 1].name,
        ) <= 0,
      );
    }
  }

  // Test 6: Sorting by name descending (reverse alphabetically)
  const nameDescResult: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        order_by: "name",
        direction: "desc",
        limit,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(nameDescResult);

  // Verify name descending sort
  if (nameDescResult.data.length > 1) {
    for (let i = 0; i < nameDescResult.data.length - 1; i++) {
      TestValidator.predicate(
        `name descending sort at position ${i}`,
        nameDescResult.data[i].name.localeCompare(
          nameDescResult.data[i + 1].name,
        ) >= 0,
      );
    }
  }

  // Test 7: Pagination with sorting
  const page1Result: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        page: 1,
        limit: 5,
        order_by: "name",
        direction: "asc",
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(page1Result);

  TestValidator.predicate(
    "pagination should respect limit",
    page1Result.data.length <= 5,
  );

  TestValidator.predicate(
    "pagination info should be valid",
    page1Result.pagination.current === 1,
  );

  TestValidator.predicate(
    "pagination limit should match request",
    page1Result.pagination.limit === 5,
  );

  // Test 8: Verify sort parameter combinations work together
  const combinedSortResult: IPageIDiscussionBoardCategory.ISummary =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        page: 1,
        limit: 10,
        order_by: "display_order",
        direction: "desc",
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(combinedSortResult);

  // Verify display_order descending sort
  if (combinedSortResult.data.length > 1) {
    for (let i = 0; i < combinedSortResult.data.length - 1; i++) {
      TestValidator.predicate(
        `display_order descending sort at position ${i}`,
        combinedSortResult.data[i].display_order >=
          combinedSortResult.data[i + 1].display_order,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCategory";

/**
 * Test category active status filtering to ensure proper visibility control.
 *
 * Verifies that filtering by is_active=true returns only categories with active
 * status available for member selection. Test that filtering by is_active=false
 * returns only inactive categories. Verify that omitting the is_active filter
 * returns all categories regardless of active status. Test that the active
 * status properly controls whether categories appear in member-facing category
 * selections and navigation. Validate that inactive categories retain their
 * articles but are not shown in member UI.
 *
 * Steps:
 *
 * 1. Retrieve all categories without active status filter
 * 2. Retrieve only active categories (is_active=true)
 * 3. Retrieve only inactive categories (is_active=false)
 * 4. Verify filtering accuracy and data consistency
 * 5. Validate pagination works with status filters
 * 6. Verify article counts are preserved for inactive categories
 */
export async function test_api_category_active_status_filter(
  connection: api.IConnection,
) {
  // Step 1: Retrieve all categories without active status filter
  const allCategoriesResponse =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        page: 1,
        limit: 50,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(allCategoriesResponse);
  TestValidator.predicate(
    "all categories response has pagination",
    allCategoriesResponse.pagination !== null &&
      allCategoriesResponse.pagination !== undefined,
  );
  TestValidator.predicate(
    "all categories response has data array",
    Array.isArray(allCategoriesResponse.data),
  );

  const totalCategories = allCategoriesResponse.pagination.records;
  TestValidator.predicate(
    "total categories count is non-negative",
    totalCategories >= 0,
  );

  // Step 2: Retrieve only active categories (is_active=true)
  const activeCategoriesResponse =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        page: 1,
        limit: 50,
        is_active: true,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(activeCategoriesResponse);
  TestValidator.predicate(
    "active categories response is valid",
    activeCategoriesResponse.data !== null &&
      activeCategoriesResponse.data !== undefined,
  );

  // Step 3: Retrieve only inactive categories (is_active=false)
  const inactiveCategoriesResponse =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        page: 1,
        limit: 50,
        is_active: false,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(inactiveCategoriesResponse);
  TestValidator.predicate(
    "inactive categories response is valid",
    inactiveCategoriesResponse.data !== null &&
      inactiveCategoriesResponse.data !== undefined,
  );

  // Step 4: Verify filtering accuracy and data consistency
  const activeCount = activeCategoriesResponse.pagination.records;
  const inactiveCount = inactiveCategoriesResponse.pagination.records;

  TestValidator.predicate("active category count is valid", activeCount >= 0);
  TestValidator.predicate(
    "inactive category count is valid",
    inactiveCount >= 0,
  );

  // Verify all active categories have required fields
  if (activeCategoriesResponse.data.length > 0) {
    const firstActive = activeCategoriesResponse.data[0];
    TestValidator.predicate(
      "active category has id",
      typeof firstActive.id === "string" && firstActive.id.length > 0,
    );
    TestValidator.predicate(
      "active category has name",
      typeof firstActive.name === "string" && firstActive.name.length > 0,
    );
    TestValidator.predicate(
      "active category has slug",
      typeof firstActive.slug === "string" && firstActive.slug.length > 0,
    );
    TestValidator.predicate(
      "active category has display_order",
      typeof firstActive.display_order === "number",
    );
    TestValidator.predicate(
      "active category has article_count",
      typeof firstActive.article_count === "number" &&
        firstActive.article_count >= 0,
    );
  }

  // Step 5: Validate pagination works with status filters
  if (activeCount > 10) {
    const activePage2Response =
      await api.functional.discussionBoard.categories.index(connection, {
        body: {
          page: 2,
          limit: 10,
          is_active: true,
        } satisfies IDiscussionBoardCategory.IRequest,
      });
    typia.assert(activePage2Response);
    TestValidator.predicate(
      "pagination limit is respected",
      activePage2Response.data.length <= 10,
    );
    TestValidator.predicate(
      "page 2 has different content than page 1",
      activePage2Response.pagination.current === 2,
    );
  }

  // Step 6: Verify article counts are preserved for inactive categories
  if (inactiveCategoriesResponse.data.length > 0) {
    const firstInactive = inactiveCategoriesResponse.data[0];
    TestValidator.predicate(
      "inactive category has article count",
      typeof firstInactive.article_count === "number" &&
        firstInactive.article_count >= 0,
    );
  }

  // Step 7: Test sorting with active status filter
  const sortedActiveResponse =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        page: 1,
        limit: 50,
        is_active: true,
        order_by: "name",
        direction: "asc",
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(sortedActiveResponse);
  TestValidator.predicate(
    "sorted active categories returned",
    sortedActiveResponse.data.length >= 0,
  );

  // Step 8: Test search with active status filter
  if (activeCategoriesResponse.data.length > 0) {
    const firstCategory = activeCategoriesResponse.data[0];
    const searchTerm = firstCategory.name.substring(
      0,
      Math.min(3, firstCategory.name.length),
    );
    const searchResponse =
      await api.functional.discussionBoard.categories.index(connection, {
        body: {
          page: 1,
          limit: 50,
          is_active: true,
          search: searchTerm,
        } satisfies IDiscussionBoardCategory.IRequest,
      });
    typia.assert(searchResponse);
    TestValidator.predicate(
      "search with active filter returns valid response",
      searchResponse.data.length >= 0,
    );
  }

  // Step 9: Verify undefined is_active parameter returns all categories
  const undefinedActiveResponse =
    await api.functional.discussionBoard.categories.index(connection, {
      body: {
        page: 1,
        limit: 50,
      } satisfies IDiscussionBoardCategory.IRequest,
    });
  typia.assert(undefinedActiveResponse);
  TestValidator.predicate(
    "undefined is_active returns all categories",
    undefinedActiveResponse.pagination.records >= 0,
  );

  // Step 10: Consistency check - all categories count should be >= active count
  TestValidator.predicate(
    "all categories count includes active categories",
    totalCategories >= activeCount,
  );
  TestValidator.predicate(
    "all categories count includes inactive categories",
    totalCategories >= inactiveCount,
  );

  // Final validation
  TestValidator.predicate(
    "active status filtering test completed successfully",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
