import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test successful moderator authentication using email credentials.
 *
 * This test validates the core authentication workflow for moderators. A
 * moderator with an active account logs in by providing their registered email
 * and correct password. The system validates credentials against the stored
 * password hash, verifies the account status is 'active', creates a new session
 * record with security context (IP, referrer, href), and returns JWT access and
 * refresh tokens along with moderator summary information.
 *
 * Test steps:
 *
 * 1. Generate valid email and password credentials for moderator login
 * 2. Create login request with email, password, IP address, href, and referrer
 * 3. Call the moderator login API endpoint
 * 4. Validate the response contains JWT tokens (access and refresh)
 * 5. Verify token expiration timestamps are valid future dates
 * 6. Validate moderator summary information (id, display_name, account_status)
 * 7. Confirm account_status is 'active' for successful login
 */
export async function test_api_moderator_authentication_successful_login_with_email(
  connection: api.IConnection,
) {
  // Step 1: Generate valid moderator login credentials
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12); // Valid password format
  const ipAddress = "192.168.1.100"; // Sample IPv4 address for testing
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  // Step 2 & 3: Create login request and call moderator login API
  const loginRequest = {
    email,
    password,
    ip: ipAddress,
    href,
    referrer,
  } satisfies IDiscussionBoardModerator.ILogin;

  const response = await api.functional.auth.moderator.login(connection, {
    body: loginRequest,
  });

  // Step 4: Validate response type and presence of JWT tokens
  typia.assert(response);
  typia.assert<IDiscussionBoardModerator.IAuthorized>(response);

  // Verify tokens exist and are non-empty strings
  TestValidator.predicate(
    "access token should be a non-empty string",
    response.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be a non-empty string",
    response.token.refresh.length > 0,
  );

  // Step 5: Validate token expiration timestamps
  const accessTokenExpiry = new Date(response.token.expired_at);
  const refreshTokenExpiry = new Date(response.token.refreshable_until);
  const now = new Date();

  TestValidator.predicate(
    "access token expiration should be in the future",
    accessTokenExpiry.getTime() > now.getTime(),
  );
  TestValidator.predicate(
    "refresh token expiration should be in the future",
    refreshTokenExpiry.getTime() > now.getTime(),
  );
  TestValidator.predicate(
    "refresh token should expire after access token",
    refreshTokenExpiry.getTime() >= accessTokenExpiry.getTime(),
  );

  // Step 6: Validate moderator summary information
  const moderator = response.moderator;
  TestValidator.predicate(
    "moderator id should be a valid UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      moderator.id,
    ),
  );
  TestValidator.predicate(
    "moderator display_name should not be empty",
    moderator.display_name.length > 0,
  );
  TestValidator.predicate(
    "moderator display_name should be within length constraints",
    moderator.display_name.length >= 1 && moderator.display_name.length <= 50,
  );

  // Step 7: Confirm account_status is 'active' for successful login
  TestValidator.equals(
    "moderator account_status should be active",
    moderator.account_status,
    "active",
  );

  // Verify the authenticated moderator id is returned
  TestValidator.predicate(
    "response should contain moderator id",
    response.id === moderator.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test successful moderator authentication using username credentials.
 *
 * Validates that a moderator with an active account can authenticate using
 * their username instead of email. The system performs case-insensitive
 * username lookup, validates the password against the stored hash, verifies the
 * moderator has an 'active' account status, creates a secure session record
 * with IP/href/referrer context, and returns JWT tokens (access and refresh)
 * along with moderator summary information.
 *
 * This test ensures:
 *
 * 1. Username-based authentication works correctly
 * 2. Password validation succeeds with correct credentials
 * 3. Only active moderators can log in
 * 4. Session is properly created with security context
 * 5. JWT tokens are returned in the response
 * 6. Moderator summary includes correct identification and status
 */
export async function test_api_moderator_authentication_successful_login_with_username(
  connection: api.IConnection,
) {
  // Generate test credentials for moderator login
  const username = typia.random<
    string &
      tags.MinLength<3> &
      tags.MaxLength<30> &
      tags.Pattern<"^[a-zA-Z0-9_-]+$">
  >();
  const password = RandomGenerator.alphabets(12);
  const testUrl = "https://example.com/moderator/login";
  const testReferrer = "https://example.com/moderator";
  const testIp = "192.168.1.100";

  // Prepare login request body with username
  const loginBody = {
    username: username,
    password: password,
    href: testUrl,
    referrer: testReferrer,
    ip: testIp,
  } satisfies IDiscussionBoardModerator.ILogin;

  // Attempt moderator login with username credentials
  const response: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.login(connection, {
      body: loginBody,
    });

  // Validate response is properly typed and contains all required data
  typia.assert(response);

  // Validate that authentication was successful by checking moderator ID exists
  TestValidator.predicate(
    "moderator ID should be present after successful authentication",
    response.id.length > 0,
  );

  // Validate moderator account status is 'active' (login restriction enforcement)
  TestValidator.equals(
    "authenticated moderator should have active account status",
    response.moderator.account_status,
    "active",
  );

  // Validate moderator summary ID matches the authenticated moderator ID
  TestValidator.equals(
    "moderator summary ID should match authenticated moderator ID",
    response.moderator.id,
    response.id,
  );

  // Validate JWT tokens were issued and are not empty
  TestValidator.predicate(
    "access token should be issued after successful login",
    response.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be issued after successful login",
    response.token.refresh.length > 0,
  );

  // Validate token expiration timing (refresh token validity extends beyond access token)
  const accessExpiry = new Date(response.token.expired_at).getTime();
  const refreshExpiry = new Date(response.token.refreshable_until).getTime();
  TestValidator.predicate(
    "refresh token should have extended validity period compared to access token",
    refreshExpiry > accessExpiry,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test authentication failure when moderator provides incorrect password.
 *
 * A moderator provides a valid email or username but an incorrect password. The
 * system performs bcrypt verification against the stored password_hash and
 * rejects the authentication attempt. The system does not reveal whether the
 * email/username exists, returning an appropriate error message. No session
 * record is created for failed authentication attempts. This validates password
 * validation security and prevents information leakage about registered
 * accounts.
 *
 * Test flow:
 *
 * 1. Test with a known email and incorrect password
 * 2. Test with a known username and incorrect password
 * 3. Test with a non-existent email and password (security verification)
 * 4. Verify all attempts fail consistently without revealing account information
 */
export async function test_api_moderator_authentication_invalid_credentials_wrong_password(
  connection: api.IConnection,
) {
  // Generate test credentials for various login scenarios
  const testEmail = typia.random<string & tags.Format<"email">>();
  const testUsername = RandomGenerator.alphaNumeric(15);
  const wrongPassword = "IncorrectPassword123!@#";

  // Create test URI and referrer for the login requests
  const testUri = "https://example.com/admin/login";
  const testReferrer = "https://example.com/";

  // Test 1: Attempt to login with email and incorrect password
  // This should fail since the password doesn't match the stored password_hash
  const wrongPasswordLoginWithEmail = {
    email: testEmail,
    password: wrongPassword,
    href: testUri,
    referrer: testReferrer,
  } satisfies IDiscussionBoardModerator.ILogin;

  await TestValidator.error(
    "login with email and incorrect password should fail",
    async () => {
      await api.functional.auth.moderator.login(connection, {
        body: wrongPasswordLoginWithEmail,
      });
    },
  );

  // Test 2: Attempt to login with username and incorrect password
  // This should also fail - the system validates password against bcrypt hash
  const wrongPasswordLoginWithUsername = {
    username: testUsername,
    password: wrongPassword,
    href: testUri,
    referrer: testReferrer,
  } satisfies IDiscussionBoardModerator.ILogin;

  await TestValidator.error(
    "login with username and incorrect password should fail",
    async () => {
      await api.functional.auth.moderator.login(connection, {
        body: wrongPasswordLoginWithUsername,
      });
    },
  );

  // Test 3: Verify security - non-existent email with any password fails
  // This ensures the system doesn't leak account existence information
  const nonExistentEmail = typia.random<string & tags.Format<"email">>();
  const nonExistentLoginBody = {
    email: nonExistentEmail,
    password: wrongPassword,
    href: testUri,
    referrer: testReferrer,
  } satisfies IDiscussionBoardModerator.ILogin;

  await TestValidator.error(
    "login with non-existent email should fail without revealing account status",
    async () => {
      await api.functional.auth.moderator.login(connection, {
        body: nonExistentLoginBody,
      });
    },
  );

  // Test 4: Verify security - non-existent username with any password also fails
  // Ensures consistent error handling that doesn't distinguish between
  // "user not found" and "wrong password"
  const nonExistentUsername = RandomGenerator.alphaNumeric(20);
  const nonExistentUsernameLoginBody = {
    username: nonExistentUsername,
    password: wrongPassword,
    href: testUri,
    referrer: testReferrer,
  } satisfies IDiscussionBoardModerator.ILogin;

  await TestValidator.error(
    "login with non-existent username should fail without revealing account status",
    async () => {
      await api.functional.auth.moderator.login(connection, {
        body: nonExistentUsernameLoginBody,
      });
    },
  );
}

