import type { IPageIDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationAction";

export async function test_api_moderation_actions_sorting_by_moderator(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphabets(8);
  const moderatorDisplayName = RandomGenerator.name();

  const authResult = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: moderatorUsername,
      password: "SecurePassword123",
      display_name: moderatorDisplayName,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(authResult);

  // Step 2: Fetch moderation actions sorted by moderatorId in ascending order
  const ascendingResult =
    await api.functional.discussionBoard.moderator.moderation.actions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 100,
          orderBy: "moderatorId",
          order: "asc",
        } satisfies IDiscussionBoardModerationAction.IRequest,
      },
    );
  typia.assert(ascendingResult);

  // Step 3: Verify ascending sort order by moderatorId
  if (ascendingResult.data && ascendingResult.data.length > 1) {
    const moderatorIds = ascendingResult.data.map(
      (action) => action.moderatorId,
    );
    for (let i = 0; i < moderatorIds.length - 1; i++) {
      TestValidator.predicate(
        `moderator ID at position ${i} should be <= moderator ID at position ${i + 1} in ascending order`,
        moderatorIds[i] <= moderatorIds[i + 1],
      );
    }
  }

  // Step 4: Fetch moderation actions sorted by moderatorId in descending order
  const descendingResult =
    await api.functional.discussionBoard.moderator.moderation.actions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 100,
          orderBy: "moderatorId",
          order: "desc",
        } satisfies IDiscussionBoardModerationAction.IRequest,
      },
    );
  typia.assert(descendingResult);

  // Step 5: Verify descending sort order by moderatorId
  if (descendingResult.data && descendingResult.data.length > 1) {
    const moderatorIds = descendingResult.data.map(
      (action) => action.moderatorId,
    );
    for (let i = 0; i < moderatorIds.length - 1; i++) {
      TestValidator.predicate(
        `moderator ID at position ${i} should be >= moderator ID at position ${i + 1} in descending order`,
        moderatorIds[i] >= moderatorIds[i + 1],
      );
    }
  }

  // Step 6: Verify both result sets contain same number of actions
  if (ascendingResult.data && descendingResult.data) {
    TestValidator.equals(
      "ascending and descending results should have same data count",
      ascendingResult.data.length,
      descendingResult.data.length,
    );
  }

  // Step 7: Verify reverse order relationship between ascending and descending results
  if (
    ascendingResult.data &&
    descendingResult.data &&
    ascendingResult.data.length > 0
  ) {
    const lastAscending = ascendingResult.data[ascendingResult.data.length - 1];
    const firstDescending = descendingResult.data[0];

    TestValidator.equals(
      "last action ID in ascending order should match first action ID in descending order",
      lastAscending.id,
      firstDescending.id,
    );

    const firstAscending = ascendingResult.data[0];
    const lastDescending =
      descendingResult.data[descendingResult.data.length - 1];

    TestValidator.equals(
      "first action ID in ascending order should match last action ID in descending order",
      firstAscending.id,
      lastDescending.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationAction";

/**
 * Test basic pagination functionality for moderation actions listing.
 *
 * This test verifies that moderators can efficiently navigate through
 * moderation action audit trails using pagination. It validates that:
 *
 * 1. Moderator authentication works correctly
 * 2. Pagination with page=1 and limit=10 returns correct data
 * 3. Page metadata (current, limit, records, pages) is accurate
 * 4. Multiple pages can be retrieved without data duplication
 * 5. Page boundaries are respected across navigation
 *
 * The test flows through these steps:
 *
 * 1. Register a moderator account
 * 2. Request first page (page 1, limit 10)
 * 3. Validate pagination metadata
 * 4. Request second page to verify no data duplication
 * 5. Validate that pagination limits are enforced
 */
export async function test_api_moderation_actions_pagination_basic(
  connection: api.IConnection,
) {
  // Step 1: Register and authenticate as moderator
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        username: RandomGenerator.alphabets(12),
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Request first page of moderation actions (page=1, limit=10)
  const firstPage: IPageIDiscussionBoardModerationAction.ISummary =
    await api.functional.discussionBoard.moderator.moderation.actions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardModerationAction.IRequest,
      },
    );
  typia.assert(firstPage);

  // Step 3: Validate pagination metadata for first page
  TestValidator.equals(
    "first page current number is 1",
    firstPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "first page limit is 10",
    firstPage.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "first page has valid records count",
    firstPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "first page has valid pages count",
    firstPage.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "first page data array length does not exceed limit",
    firstPage.data.length <= 10,
  );

  // Step 4: Validate that records count matches data array length on first page
  if (firstPage.pagination.records > 0) {
    if (firstPage.pagination.current === firstPage.pagination.pages) {
      // Last page - may have fewer records
      TestValidator.predicate(
        "last page data length matches remaining records",
        firstPage.data.length ===
          (firstPage.pagination.records % firstPage.pagination.limit === 0
            ? firstPage.pagination.limit
            : firstPage.pagination.records % firstPage.pagination.limit),
      );
    } else {
      // Not last page - should have exactly limit records
      TestValidator.equals(
        "non-last page has exactly limit records",
        firstPage.data.length,
        10,
      );
    }
  }

  // Step 5: Request second page to verify pagination progression
  if (firstPage.pagination.pages > 1) {
    const secondPage: IPageIDiscussionBoardModerationAction.ISummary =
      await api.functional.discussionBoard.moderator.moderation.actions.index(
        connection,
        {
          body: {
            page: 2,
            limit: 10,
          } satisfies IDiscussionBoardModerationAction.IRequest,
        },
      );
    typia.assert(secondPage);

    // Step 6: Validate second page metadata
    TestValidator.equals(
      "second page current number is 2",
      secondPage.pagination.current,
      2,
    );
    TestValidator.equals(
      "second page limit is 10",
      secondPage.pagination.limit,
      10,
    );

    // Step 7: Verify no data duplication between pages
    const firstPageIds = new Set(firstPage.data.map((action) => action.id));
    const secondPageIds = new Set(secondPage.data.map((action) => action.id));
    const intersection = Array.from(firstPageIds).filter((id) =>
      secondPageIds.has(id),
    );
    TestValidator.predicate(
      "no data duplication between first and second page",
      intersection.length === 0,
    );

    // Step 8: Validate that second page records count is consistent
    TestValidator.equals(
      "second page has same total records as first page",
      secondPage.pagination.records,
      firstPage.pagination.records,
    );
    TestValidator.equals(
      "second page has same pages count as first page",
      secondPage.pagination.pages,
      firstPage.pagination.pages,
    );
  }

  // Step 9: Test edge case - request with limit=1 to test minimum pagination
  const limitOnePage: IPageIDiscussionBoardModerationAction.ISummary =
    await api.functional.discussionBoard.moderator.moderation.actions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 1,
        } satisfies IDiscussionBoardModerationAction.IRequest,
      },
    );
  typia.assert(limitOnePage);

  TestValidator.equals(
    "limit one page has correct limit",
    limitOnePage.pagination.limit,
    1,
  );
  TestValidator.predicate(
    "limit one page data has at most 1 item",
    limitOnePage.data.length <= 1,
  );

  // Step 10: Verify pagination calculations are consistent
  TestValidator.predicate(
    "pages calculation is correct",
    limitOnePage.pagination.pages ===
      Math.ceil(
        limitOnePage.pagination.records / limitOnePage.pagination.limit,
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationAction";

/**
 * Test pagination limit boundaries and maximum page size for moderation
 * actions.
 *
 * This test validates that the moderation actions listing API properly enforces
 * pagination limit constraints and correctly calculates pagination metadata for
 * different page sizes. The test authenticates as a moderator and requests the
 * moderation actions audit trail with various limit values to verify:
 *
 * 1. Minimum limit boundary (limit=1) returns 1 action per page
 * 2. Typical values (limit=10, 25, 50) work correctly
 * 3. Maximum allowed limit (limit=100) is respected
 * 4. Total pages calculation is accurate for different limits
 * 5. The API respects the limits and returns appropriate page sizes
 *
 * Test workflow:
 *
 * 1. Register and authenticate as a moderator
 * 2. Request moderation actions with limit=1, verify 1 item returned
 * 3. Request with limit=10, verify correct pagination info
 * 4. Request with limit=25, verify pagination calculations
 * 5. Request with limit=50, verify pagination calculations
 * 6. Request with limit=100 (maximum), verify maximum is respected
 * 7. Validate that pages calculation is accurate: pages = ceil(records / limit)
 */
export async function test_api_moderation_actions_pagination_limit_boundary(
  connection: api.IConnection,
) {
  // Register and authenticate as moderator
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      username: RandomGenerator.alphabets(10),
      password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Test with limit=1 (minimum meaningful limit)
  const result1 =
    await api.functional.discussionBoard.moderator.moderation.actions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 1,
        } satisfies IDiscussionBoardModerationAction.IRequest,
      },
    );
  typia.assert(result1);
  TestValidator.equals(
    "limit=1 should return max 1 item per page",
    result1.data.length <= 1,
    true,
  );
  TestValidator.equals(
    "pagination limit should be 1",
    result1.pagination.limit,
    1,
  );

  // Test with limit=10
  const result10 =
    await api.functional.discussionBoard.moderator.moderation.actions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardModerationAction.IRequest,
      },
    );
  typia.assert(result10);
  TestValidator.equals(
    "limit=10 should return max 10 items per page",
