import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSearchResult";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSearchResult";

/**
 * Test that the search endpoint is publicly accessible without authentication.
 *
 * Verifies that guest users can perform searches across the discussion board
 * without providing authentication credentials. The test validates that public
 * search results return only published articles and exclude
 * draft/pending/rejected articles. It ensures public search results include
 * article summaries with titles, bodies, creators, and categories while
 * respecting visibility rules. The test confirms that guest access to search
 * does not provide administrative capabilities.
 *
 * Test workflow:
 *
 * 1. Create an unauthenticated connection (empty headers)
 * 2. Perform basic keyword search without authentication
 * 3. Validate search results contain only published articles
 * 4. Test search with category filtering
 * 5. Test search with pagination
 * 6. Verify result structure includes required fields
 * 7. Validate that no draft/pending articles are visible
 * 8. Verify visibility rules prevent non-published article access
 */
export async function test_api_search_public_access_no_auth(
  connection: api.IConnection,
) {
  // Create an unauthenticated connection for public access testing
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // Test 1: Basic keyword search without authentication
  const searchQuery = RandomGenerator.paragraph({ sentences: 2 });
  const basicSearchResult: IPageIDiscussionBoardSearchResult =
    await api.functional.discussionBoard.search.index(unauthConn, {
      body: {
        q: searchQuery,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(basicSearchResult);

  // Validate search response structure
  TestValidator.predicate(
    "search result has pagination",
    basicSearchResult.pagination !== null &&
      basicSearchResult.pagination !== undefined,
  );
  TestValidator.predicate(
    "search result has data array",
    Array.isArray(basicSearchResult.data),
  );

  // Test 2: Validate that only published articles are in results
  for (const result of basicSearchResult.data) {
    typia.assert(result);

    // Check that articles in results are published
    for (const article of result.articles) {
      TestValidator.equals(
        "article status should be published",
        article.status,
        "published",
      );

      // Verify article has required fields
      TestValidator.predicate(
        "article has id",
        article.id !== null && article.id !== undefined,
      );
      TestValidator.predicate(
        "article has title",
        article.title !== null &&
          article.title !== undefined &&
          article.title.length > 0,
      );
      TestValidator.predicate(
        "article has creator",
        article.creator !== null && article.creator !== undefined,
      );
      TestValidator.predicate(
        "article has category",
        article.category !== null && article.category !== undefined,
      );
    }
  }

  // Test 3: Search with category filtering
  const categoryFilter = [typia.random<string & tags.Format<"uuid">>()];
  const categorySearchResult: IPageIDiscussionBoardSearchResult =
    await api.functional.discussionBoard.search.index(unauthConn, {
      body: {
        q: searchQuery,
        categories: categoryFilter,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(categorySearchResult);
  TestValidator.predicate(
    "category filtered search returns results",
    categorySearchResult.data !== null &&
      categorySearchResult.data !== undefined,
  );

  // Test 4: Search with pagination
  const paginatedSearchResult: IPageIDiscussionBoardSearchResult =
    await api.functional.discussionBoard.search.index(unauthConn, {
      body: {
        q: searchQuery,
        page: 1,
        limit: 10,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(paginatedSearchResult);

  TestValidator.predicate(
    "pagination has current page",
    paginatedSearchResult.pagination.current !== null &&
      paginatedSearchResult.pagination.current !== undefined,
  );
  TestValidator.predicate(
    "pagination has limit",
    paginatedSearchResult.pagination.limit !== null &&
      paginatedSearchResult.pagination.limit !== undefined,
  );
  TestValidator.predicate(
    "pagination has total records",
    paginatedSearchResult.pagination.records !== null &&
      paginatedSearchResult.pagination.records !== undefined,
  );

  // Test 5: Verify search result content structure
  if (paginatedSearchResult.data.length > 0) {
    const firstResult = paginatedSearchResult.data[0];
    typia.assert(firstResult);

    TestValidator.predicate(
      "result has articles array",
      Array.isArray(firstResult.articles),
    );
    TestValidator.predicate(
      "result has comments array",
      Array.isArray(firstResult.comments),
    );
    TestValidator.predicate(
      "result has total_results count",
      typeof firstResult.total_results === "number",
    );
    TestValidator.predicate(
      "result has result_types breakdown",
      firstResult.result_types !== null &&
        firstResult.result_types !== undefined,
    );

    // Validate creator information in articles
    for (const article of firstResult.articles) {
      TestValidator.predicate(
        "article creator has id",
        article.creator.id !== null && article.creator.id !== undefined,
      );
      TestValidator.predicate(
        "article creator has display_name",
        article.creator.display_name !== null &&
          article.creator.display_name !== undefined &&
          article.creator.display_name.length > 0,
      );
      TestValidator.predicate(
        "article creator has account_status",
        article.creator.account_status !== null &&
          article.creator.account_status !== undefined,
      );
    }
  }

  // Test 6: Search with status filter shows visibility rule enforcement
  const statusFilterResult: IPageIDiscussionBoardSearchResult =
    await api.functional.discussionBoard.search.index(unauthConn, {
      body: {
        q: searchQuery,
        status: ["published"],
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(statusFilterResult);

  // Verify all returned articles are published
  for (const result of statusFilterResult.data) {
    for (const article of result.articles) {
      TestValidator.equals(
        "filtered article must be published",
        article.status,
        "published",
      );
    }
  }

  // Test 7: Test with empty search results
  const uniqueQuery = RandomGenerator.alphaNumeric(16);
  const emptySearchResult: IPageIDiscussionBoardSearchResult =
    await api.functional.discussionBoard.search.index(unauthConn, {
      body: {
        q: uniqueQuery,
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(emptySearchResult);
  TestValidator.predicate(
    "empty search returns valid structure",
    emptySearchResult.pagination !== null && emptySearchResult.data !== null,
  );

  // Test 8: Verify visibility rules prevent draft article access
  // Even if guest tries to request multiple statuses, only published are returned
  const visibilityTestResult: IPageIDiscussionBoardSearchResult =
    await api.functional.discussionBoard.search.index(unauthConn, {
      body: {
        q: searchQuery,
        status: ["pending_approval", "published", "rejected"],
      } satisfies IDiscussionBoardArticle.IRequest,
    });
  typia.assert(visibilityTestResult);

  // Verify that even with multiple status filters, guest only sees published
  for (const result of visibilityTestResult.data) {
    for (const article of result.articles) {
      TestValidator.equals(
        "visibility rules enforce published-only for guests",
        article.status,
        "published",
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Test member discovery functionality allowing users to browse registered
 * members.
 *
 * This test validates the public member listing API by:
 *
 * 1. Creating multiple member accounts to populate the member list
 * 2. Performing member searches without filters to retrieve active members
 * 3. Validating that responses include only public profile information
 * 4. Testing pagination with different page and limit values
 * 5. Verifying default sorting by creation_at (newest members first)
 * 6. Confirming pagination metadata accurately reflects member counts
 * 7. Ensuring email addresses and sensitive details are not exposed
 *
 * The test ensures member discovery provides safe public browsing without
 * compromising member privacy by excluding personal information.
 */
export async function test_api_members_list_public_discovery(
  connection: api.IConnection,
) {
  // Step 1: Create multiple member accounts
  const memberCount = 5;
  const createdMembers: IDiscussionBoardMember.IAuthorized[] = [];

  for (let i = 0; i < memberCount; i++) {
    const member = await api.functional.auth.member.join(connection, {
      body: {
        email:
          typia
            .random<string & tags.Format<"email">>()
            .split("@")[0]
            .substring(0, 20) + `_${i}@test.example.com`,
        username: `testuser_${i}_${RandomGenerator.alphaNumeric(6)}`,
        display_name: `Test User ${i}`,
        password: `Password${i}123!`,
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    createdMembers.push(member);
  }

  // Step 2: Test basic member listing without filters
  const basicListResponse = await api.functional.discussionBoard.members.index(
    connection,
    {
      body: {} satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(basicListResponse);
  TestValidator.predicate(
    "response should contain pagination info",
    basicListResponse.pagination !== undefined,
  );
  TestValidator.predicate(
    "response should contain member data array",
    Array.isArray(basicListResponse.data),
  );
  TestValidator.predicate(
    "data array should not be empty",
    basicListResponse.data.length > 0,
  );

  // Step 3: Validate pagination metadata
  const pagination = basicListResponse.pagination;
  TestValidator.predicate(
    "current page should be >= 1",
    pagination.current >= 1,
  );
  TestValidator.predicate("limit should be > 0", pagination.limit > 0);
  TestValidator.predicate(
    "records should match created members or more",
    pagination.records >= memberCount,
  );
  TestValidator.predicate(
    "pages should be calculated correctly",
    pagination.pages >= 1,
  );

  // Step 4: Validate member summary data structure
  if (basicListResponse.data.length > 0) {
    const member = basicListResponse.data[0];
    TestValidator.predicate("member should have id", member.id !== undefined);
    TestValidator.predicate(
      "member should have display_name",
      member.display_name !== undefined,
    );
    TestValidator.predicate(
      "member should have account_status",
      member.account_status !== undefined,
    );
    TestValidator.predicate(
      "member should have created_at",
      member.created_at !== undefined,
    );
  }

  // Step 5: Test pagination with different limit values
  const smallLimitResponse = await api.functional.discussionBoard.members.index(
    connection,
    {
      body: {
        limit: 2,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(smallLimitResponse);
  TestValidator.predicate(
    "small limit should return 2 or fewer items",
    smallLimitResponse.data.length <= 2,
  );
  TestValidator.equals(
    "pagination limit should match request",
    smallLimitResponse.pagination.limit,
    2,
  );

  // Step 6: Test pagination with different page numbers
  if (smallLimitResponse.pagination.pages > 1) {
    const secondPageResponse =
      await api.functional.discussionBoard.members.index(connection, {
        body: {
          limit: 2,
          page: 2,
        } satisfies IDiscussionBoardMember.IRequest,
      });
    typia.assert(secondPageResponse);
    TestValidator.equals(
      "second page current should be 2",
      secondPageResponse.pagination.current,
      2,
    );
    TestValidator.predicate(
      "second page should have members",
      secondPageResponse.data.length > 0,
    );
  }

  // Step 7: Test filtering by account_status
  const activeOnlyResponse = await api.functional.discussionBoard.members.index(
    connection,
    {
      body: {
        account_status: ["active"],
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(activeOnlyResponse);
  TestValidator.predicate(
    "active filter should return results",
    activeOnlyResponse.data.length >= 0,
  );
  if (activeOnlyResponse.data.length > 0) {
    TestValidator.equals(
      "all returned members should have active status",
      activeOnlyResponse.data[0].account_status,
      "active",
    );
  }

  // Step 8: Test search functionality
  const firstMemberName = basicListResponse.data[0]?.display_name;
  if (firstMemberName) {
    const searchResponse = await api.functional.discussionBoard.members.index(
      connection,
      {
        body: {
          search: firstMemberName,
        } satisfies IDiscussionBoardMember.IRequest,
      },
    );
    typia.assert(searchResponse);
    TestValidator.predicate(
      "search should return results",
      searchResponse.data.length >= 0,
    );
  }

  // Step 9: Test default sorting (newest members first by created_at)
  const sortedResponse = await api.functional.discussionBoard.members.index(
    connection,
    {
      body: {
        sort_by: "created_at",
        sort_order: "desc",
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(sortedResponse);
  TestValidator.predicate(
    "sorted response should have data",
    sortedResponse.data.length > 0,
  );
  if (sortedResponse.data.length > 1) {
    const first = new Date(sortedResponse.data[0].created_at);
    const second = new Date(sortedResponse.data[1].created_at);
    TestValidator.predicate(
      "first member should be created after or same time as second",
      first.getTime() >= second.getTime(),
    );
  }

  // Step 10: Test that sensitive data is not exposed
  if (basicListResponse.data.length > 0) {
    const member = basicListResponse.data[0];
    const memberJson = JSON.stringify(member);
    TestValidator.predicate(
      "response should not contain email addresses",
      !memberJson.includes("@"),
    );
    TestValidator.predicate(
      "response should not contain password references",
      !memberJson.toLowerCase().includes("password"),
    );
  }

  // Step 11: Test pagination consistency with larger limit
  const largePageResponse = await api.functional.discussionBoard.members.index(
    connection,
    {
      body: {
        limit: 50,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(largePageResponse);
  TestValidator.predicate(
    "total records should be non-negative",
    largePageResponse.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages calculation should be correct",
    largePageResponse.pagination.pages >= 1,
  );
  TestValidator.predicate(
    "current data matches reported total when on first page",
    largePageResponse.data.length <= largePageResponse.pagination.records,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";

/**
 * Test filtering members by email verification status.
 *
 * This test validates that the member filtering API correctly handles the
 * email_verified parameter to filter members based on their email verification
 * status. It creates multiple member accounts with different email verification
 * statuses and tests various filter combinations to ensure the API returns
 * correct results.
 *
 * Test flow:
 *
 * 1. Create multiple member accounts (which have email_verified=false initially)
 * 2. Filter members by email_verified=true and verify no unverified members are
 *    returned
 * 3. Filter members by email_verified=false and verify only unverified members are
 *    returned
 * 4. Filter members by omitting email_verified and verify both types are returned
 * 5. Test filtering combined with search parameters
 * 6. Validate edge cases with homogeneous verification statuses
 */
export async function test_api_members_filter_by_email_verification(
  connection: api.IConnection,
) {
  // Step 1: Create multiple member accounts for testing
  const memberIds: string[] = [];

  // Create 3 unverified members (email_verified=false by default after registration)
  for (let i = 0; i < 3; i++) {
    const member = await api.functional.auth.member.join(connection, {
      body: {
        email:
          `unverified${i}_${RandomGenerator.alphaNumeric(4)}@example.com` satisfies string &
            tags.Format<"email">,
        username:
          `unverified_user_${i}_${RandomGenerator.alphaNumeric(4)}` satisfies string &
            tags.Pattern<"^[a-zA-Z0-9_-]+$">,
        display_name: `Unverified User ${i}`,
        password: "Password123456",
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    memberIds.push(member.id);
  }

  // Step 2: Filter by email_verified=true (should return no newly created members since all are unverified)
  const verifiedMembersResult =
    await api.functional.discussionBoard.members.index(connection, {
      body: {
        email_verified: true,
        limit: 100,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(verifiedMembersResult);
  TestValidator.predicate(
    "verified filter should not include newly created unverified members",
    !verifiedMembersResult.data.some((m) => memberIds.includes(m.id)),
  );

  // Step 3: Filter by email_verified=false (should return all created members)
  const unverifiedMembersResult =
    await api.functional.discussionBoard.members.index(connection, {
      body: {
        email_verified: false,
        limit: 100,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(unverifiedMembersResult);
  TestValidator.predicate(
    "unverified filter should return newly created members",
    unverifiedMembersResult.data.some((m) => memberIds.includes(m.id)),
  );

  // Step 4: Filter with null email_verified (should return all members)
  const allMembersWithNullResult =
    await api.functional.discussionBoard.members.index(connection, {
      body: {
        email_verified: null,
        limit: 100,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(allMembersWithNullResult);
  TestValidator.predicate(
    "null email_verified filter should return all members",
    allMembersWithNullResult.data.length > 0,
  );

  // Step 5: Filter with undefined email_verified (omitted parameter - should return all members)
  const allMembersWithoutFilterResult =
    await api.functional.discussionBoard.members.index(connection, {
      body: {
        limit: 100,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(allMembersWithoutFilterResult);
  TestValidator.predicate(
    "omitted email_verified filter should return all members",
    allMembersWithoutFilterResult.data.length > 0,
  );

  // Step 6: Test filtering combined with search parameter
  const searchedMembersResult =
    await api.functional.discussionBoard.members.index(connection, {
      body: {
        search: "unverified",
        email_verified: false,
        limit: 100,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(searchedMembersResult);
  TestValidator.predicate(
    "combined search and email_verified filter should apply both filters",
    searchedMembersResult.data.length >= 0,
  );

  // Step 7: Verify pagination works with email_verified filter
  const paginatedResult = await api.functional.discussionBoard.members.index(
    connection,
    {
      body: {
        email_verified: false,
        limit: 2,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(paginatedResult);
  TestValidator.predicate(
    "pagination with email_verified filter should respect limit",
    paginatedResult.data.length <= 2,
  );

  // Step 8: Test with account_status filter combined with email_verified
  const statusAndVerificationResult =
    await api.functional.discussionBoard.members.index(connection, {
      body: {
        account_status: ["active"],
        email_verified: false,
        limit: 100,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    });
  typia.assert(statusAndVerificationResult);
  TestValidator.predicate(
    "combined account_status and email_verified filter should work correctly",
    statusAndVerificationResult.data.length >= 0,
  );

  // Step 9: Test sorting with email_verified filter
  const sortedResult = await api.functional.discussionBoard.members.index(
    connection,
    {
      body: {
        email_verified: false,
        sort_by: "display_name",
        sort_order: "asc",
        limit: 100,
        page: 1,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(sortedResult);
  TestValidator.predicate(
    "sorting with email_verified filter should return results",
    sortedResult.data.length > 0,
  );

  // Step 10: Verify filter returns correct boolean result
  TestValidator.predicate(
    "all results from unverified filter should be unverified members",
    unverifiedMembersResult.data.length >= 3,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
