  const integerInactiveResult: IPageIDiscussionBoardSystemSetting =
    await api.functional.discussionBoard.moderator.systemSettings.index(
      connection,
      {
        body: {
          setting_type: "integer",
          is_active: false,
          page: 1,
          limit: 50,
